    chalk.level = savedChalkLevel;
  }

  const succeeded = results.filter((r) => r.success).length;
  const failed = results.filter((r) => !r.success).length;

  return {
    success: failed === 0,
    mode: "immediate",
    summary: { total: commands.length, succeeded, failed },
    results,
  };
}

